def exclusiveValues(a, b):
    i = j = 0
    res = []
    while i < len(a) or j < len(b):
        if j == len(b) or (i < len(a) and a[i] < b[j]):
            x = a[i]
            res.append(x)
            while i < len(a) and a[i] == x:
                i += 1
        elif i == len(a) or b[j] < a[i]:
            x = b[j]
            res.append(x)
            while j < len(b) and b[j] == x:
                j += 1
        else:
            x = a[i]
            while i < len(a) and a[i] == x:
                i += 1
            while j < len(b) and b[j] == x:
                j += 1
    return res
